package com.anxhul10.calidraw.ai\n\nimport android.os.Bundle\nimport android.widget.Button\nimport android.widget.EditText\nimport android.widget.Toast\nimport androidx.appcompat.app.AppCompatActivity\n\nclass SettingsActivity : AppCompatActivity() {\n\n    private lateinit var chatGptEditText: EditText\n    private lateinit var geminiEditText: EditText\n    private lateinit var saveButton: Button\n    private lateinit var securePreferences: SecurePreferences\n\n    companion object {\n        private const val KEY_CHATGPT = "chatgpt_key"\n        private const val KEY_GEMINI = "gemini_key"\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        setContentView(R.layout.activity_ai_settings)\n\n        securePreferences = SecurePreferences(this)\n\n        chatGptEditText = findViewById(R.id.editTextChatGPTKey)\n        geminiEditText = findViewById(R.id.editTextGeminiKey)\n        saveButton = findViewById(R.id.buttonSave)\n\n        // Load existing keys\n        chatGptEditText.setText(securePreferences.getString(KEY_CHATGPT, ""))\n        geminiEditText.setText(securePreferences.getString(KEY_GEMINI, ""))\n\n        saveButton.setOnClickListener {\n            val chatGptKey = chatGptEditText.text.toString()\n            val geminiKey = geminiEditText.text.toString()\n\n            securePreferences.putString(KEY_CHATGPT, chatGptKey)\n            securePreferences.putString(KEY_GEMINI, geminiKey)\n\n            Toast.makeText(this, "AI keys saved successfully", Toast.LENGTH_SHORT).show()\n        }\n    }\n}\n